window.products.push({"id":818422,"name":"Pop Noun Ornament - Christmas Ornament for Pop - Father's Day Ornament - Pop Gifts - Pop Definition - Keepsake Printed on Both Sides","category":"homeandappliances","retail price":15.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71OA3lwjlML._AC_SL1500_.jpg","description":"Our Ornament will be sure to be the perfect keepsake for you and your loved ones this holiday season. We provide several different kinds of designs, which make amazing gift ideas for husband, boyfriend, wife, girlfriend, grandparent, and more! The design is permanently printed on both sides onto a flat round ceramic ornament which approximately measures 2.85”. Ornament includes a gold ribbon loop for hanging. Each ornament is packed in a special bubble bag.","images":["https://m.media-amazon.com/images/I/71OA3lwjlML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"WolfeDesignPDD","source_asin":"B09CH5YMFS","category_path":"Home & Kitchen"},"sku":"BM-818422","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09CH5YMFS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09CH5YMFS","price_pending":true,"merchant_ready":false});
